import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, PointLight, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? null;

  const root = new Group();
  root.name = 'journal-card-2';

  // ---- geometry sizing from atlas region aspect (512x320 -> 1.6:1) ----
  const REGION_W = 512;
  const REGION_H = 320;
  const aspect = REGION_W / REGION_H;
  const cardHeight = 1.375;
  const cardWidth = cardHeight * aspect;

  // ---- depth plane 1: machined-metal bezel/frame (behind) ----
  const framePad = 0.09;
  const frameGeo = new PlaneGeometry(cardWidth + framePad, cardHeight + framePad, 1, 1);
  const frameMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  {
    const inkC = new Color(colors.ink);
    frameMat.colorNode = vec3(inkC.r, inkC.g, inkC.b);
  }
  frameMat.roughness = 0.55;
  frameMat.metalness = 0.5;
  frameMat.clearcoat = 0.18;
  frameMat.clearcoatRoughness = 0.4;
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.02;
  root.add(frameMesh);

  // ---- depth plane 2: subject card surface (engineered gradient + grain) ----
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  cardMat.roughness = 0.58;
  cardMat.metalness = 0.22;
  cardMat.clearcoat = 0.1;

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const gradientNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uv().y
  );
  cardMat.colorNode = gradientNode;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0.0;
  root.add(cardMesh);

  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        tex.colorSpace = THREE.SRGBColorSpace;
        // atlas region 0,0,512,320 spans the full source texture -> no offset needed
        const grainSample = texture(tex, uv());
        const grainInfluence = grainSample.r.sub(0.5).mul(float(0.08)).add(1.0);
        cardMat.colorNode = gradientNode.mul(grainInfluence);
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // keep gradient-only fallback, never crash
      });
  }

  // ---- depth plane 3: foreground accent strip (<=10% of frame area) ----
  const accentGeo = new PlaneGeometry(cardWidth * 0.42, 0.045, 1, 1);
  const accentMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  const accentColor = new Color(colors.accent);
  accentMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  accentMat.emissiveNode = vec3(accentColor.r, accentColor.g, accentColor.b).mul(float(0.9));
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.3;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-cardWidth * 0.5 + (cardWidth * 0.42) / 2 + 0.06, -cardHeight * 0.5 + 0.09, 0.03);
  root.add(accentMesh);

  // ---- node-local rim light (accent hue, capped intensity) ----
  const rimLight = new PointLight(accentColor.getHex(), 0.75, 5, 2);
  rimLight.position.set(-0.6, 0.3, 0.9);
  root.add(rimLight);

  // ---- static composition: billboard toward camera, no interactivity ----
  root.onBeforeRender = (renderer, scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    root.onBeforeRender = undefined;

    frameGeo.dispose();
    frameMat.dispose();

    cardGeo.dispose();
    cardMat.dispose();

    accentGeo.dispose();
    accentMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    root.remove(rimLight);
    root.remove(frameMesh);
    root.remove(cardMesh);
    root.remove(accentMesh);
  };

  return root;
}
